import{_ as e,o as a,c as i,a0 as o}from"./chunks/framework.DQOulFGV.js";const g=JSON.parse('{"title":"Anti-Cheat & Audit Logs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/anti-cheat.md","filePath":"guide/anti-cheat.md"}'),n={name:"guide/anti-cheat.md"};function r(s,t,l,c,d,u){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="anti-cheat-audit-logs" tabindex="-1">Anti-Cheat &amp; Audit Logs <a class="header-anchor" href="#anti-cheat-audit-logs" aria-label="Permalink to &quot;Anti-Cheat &amp; Audit Logs&quot;">​</a></h1><p>Zuta Quiz includes a robust proctoring system to maintain academic integrity during online assessments.</p><h2 id="server-side-time-synchronization" tabindex="-1">Server-Side Time Synchronization <a class="header-anchor" href="#server-side-time-synchronization" aria-label="Permalink to &quot;Server-Side Time Synchronization&quot;">​</a></h2><p>Candidates cannot bypass the exam schedule by changing their computer&#39;s local clock. The exam content (the &quot;Shell-Content&quot; pattern) is strictly locked by the server until the exact Unix Epoch start time.</p><h2 id="proctoring-logs" tabindex="-1">Proctoring Logs <a class="header-anchor" href="#proctoring-logs" aria-label="Permalink to &quot;Proctoring Logs&quot;">​</a></h2><p>The system silently records candidate behaviors in real-time. You can view these logs by navigating to <strong>Zuta Quiz</strong> &gt; <strong>Audit Logs</strong>. Recorded actions include:</p><ul><li>Exam Started / Auto-Resumed.</li><li>Tab Switching / Browser minimized.</li><li>Browser Closed / Early Exits.</li><li>Manual and Automated Submissions.</li></ul><h2 id="auto-delete-retention-settings" tabindex="-1">Auto-Delete Retention Settings <a class="header-anchor" href="#auto-delete-retention-settings" aria-label="Permalink to &quot;Auto-Delete Retention Settings&quot;">​</a></h2><p>To keep your database optimized, you can configure the system to automatically clear old logs.</p><ol><li>In the <strong>Audit Logs</strong> tab, locate the <strong>Auto-Delete Settings</strong> card.</li><li>Enter a numerical value and select the unit (<strong>Days, Months, or Years</strong>).</li><li>Click <strong>Save Settings</strong>. A daily background cron job will automatically purge logs older than your specified retention period.</li></ol>',10)])])}const m=e(n,[["render",r]]);export{g as __pageData,m as default};
